H.background();
const w = H.W, h = H.H;
const B = Math.max(0, P.B);      // tesla
const L = Math.max(0.05, P.L);   // meters (rail separation)
const v0 = Math.max(0, P.v);     // m/s peak rod speed
const R = Math.max(0.1, P.R);    // ohms (circuit resistance)
// Rod slides right and left along rails, looping (oscillates between rails' ends).
const vRod = v0 * Math.cos(t * 1.0);        // m/s, signed
const xRod = (v0 / 1.0) * Math.sin(t * 1.0); // m, position from center, bounded
const emf = B * L * vRod;   // volts (motional EMF), signed with velocity
const I = emf / R;          // amps
// Drawing geometry: two horizontal rails, rod is a vertical bar between them.
const railTop = h * 0.34, railBot = h * 0.66;
const xLeft = w * 0.18, xRight = w * 0.82;
const cx = (xLeft + xRight) / 2;
const spanPx = (xRight - xLeft) * 0.42;
const rodPx = cx + xRod * (spanPx / Math.max(0.1, v0 / 1.0)); // map bounded x to pixels, kept in span
const rx = H.clamp(rodPx, xLeft + 8, xRight - 8);
// Field region: dots = B out of page
for (let i = 0; i < 7; i++) for (let j = 0; j < 3; j++) {
  H.circle(xLeft + 30 + i * (xRight - xLeft - 60) / 6, railTop + 18 + j * (railBot - railTop - 36) / 2, 2.5, { fill: H.colors.violet });
}
H.text("B out of page", xLeft, railTop - 12, { color: H.colors.violet, size: 12 });
// rails
H.line(xLeft, railTop, xRight, railTop, { color: H.colors.axis, width: 3 });
H.line(xLeft, railBot, xRight, railBot, { color: H.colors.axis, width: 3 });
// resistor on the left end
H.rect(xLeft - 4, railTop, 8, railBot - railTop, { fill: H.colors.panel, stroke: H.colors.good, width: 2 });
H.text("R", xLeft - 22, (railTop + railBot) / 2, { color: H.colors.good, size: 14 });
// the moving rod
H.line(rx, railTop, rx, railBot, { color: H.colors.accent, width: 5 });
// velocity arrow on rod
const dir = vRod >= 0 ? 1 : -1;
H.arrow(rx, (railTop + railBot) / 2, rx + dir * 46, (railTop + railBot) / 2, { color: H.colors.accent2, width: 3 });
H.text("v", rx + dir * 52 - (dir < 0 ? 14 : 0), (railTop + railBot) / 2 - 8, { color: H.colors.accent2, size: 14 });
// force on a + charge in rod: F = qv×B -> drives current; show along rod
H.arrow(rx + 8, (railTop + railBot) / 2, rx + 8, railTop + 14, { color: H.colors.good, width: 2, head: 7 });
H.text("F = qv×B", rx + 14, railTop + 24, { color: H.colors.good, size: 11 });
H.text("Motional EMF:  ε = B · L · v", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("B = " + B.toFixed(2) + " T   L = " + L.toFixed(2) + " m   v = " + vRod.toFixed(2) + " m/s", 24, 52, { color: H.colors.sub, size: 13 });
H.text("ε = " + emf.toFixed(3) + " V    I = ε/R = " + I.toFixed(3) + " A", 24, h - 22, { color: H.colors.good, size: 14 });
H.legend([{ label: "rod & v", color: H.colors.accent2 }, { label: "rails / R", color: H.colors.good }, { label: "B field", color: H.colors.violet }], w - 170, 28);
